class MainWindow(QMainWindow, Ui_MainWindow):
    textUpdated = pyqtSignal(list)
    def __init__(self, saved_settings, parent=None):
        super(MainWindow, self).__init__(parent)
        self.setupUi(self)

        # 根据传入的状态设置文本框的内容
        self.comboBox.setCurrentText(saved_settings.get('cameraNum', '1'))
        self.comboBox_2.setCurrentText(saved_settings.get('sampleName', '刨花板'))
        self.comboBox_3.setCurrentText(saved_settings.get('detectType', '委托检验'))
        self.comboBox_4.setCurrentText(saved_settings.get('detectBatch', '1'))
        self.comboBox_5.setCurrentText(saved_settings.get('boardSpec', '20cmx20cmx2cm'))
        self.comboBox_6.setCurrentText(saved_settings.get('boardModel', 'JN BH 2440122020'))
        self.comboBox_9.setCurrentText(saved_settings.get('detectNum', '50'))
        self.comboBox_11.setCurrentText(saved_settings.get('transferRate', '1m/s'))
        self.lineEdit.setText(saved_settings.get('text1', ''))
        self.lineEdit_2.setText(saved_settings.get('text2', ''))
        self.lineEdit_3.setText(saved_settings.get('text3', ''))
        self.lineEdit_4.setText(saved_settings.get('text4', ''))

        self.pushButton.clicked.connect(self.on_save)


    def on_save(self):
        cameraNum = self.comboBox.currentText()  # 获取摄像头选择的数字
        sampleName = self.comboBox_2.currentText()  # 获取样品名称
        detectType = self.comboBox_3.currentText()  # 获取检测类别
        detectBatch = self.comboBox_4.currentText()  # 获取检测批次
        boardSpec = self.comboBox_5.currentText()   # 获取板坯规格
        boardModel = self.comboBox_6.currentText()  # 获取板坯型号
        detectNum = self.comboBox_9.currentText()   # 获取检测数量
        transferRate = self.comboBox_11.currentText()   # 获取传送带速率
        entrustUnit = self.lineEdit.text()   # 获取委托单位
        produceUnit = self.lineEdit_2.text()    # 获取生产单位
        detectPlace = self.lineEdit_3.text()    # 获取检测地点
        detectBasis = self.lineEdit_4.text()    # 获取检测依据

        #将数据存储到全局存储器中，以便在其他窗口使用，global_store.py
        shared_data['cameraNum'] = cameraNum
        shared_data['sampleName'] = sampleName
        shared_data['detectType'] = detectType
        shared_data['detectBatch'] = detectBatch
        shared_data['boardSpec'] = boardSpec
        shared_data['boardModel'] = boardModel
        shared_data['detectNum'] = detectNum
        shared_data['transferRate'] = transferRate
        shared_data['entrustUnit'] = entrustUnit
        shared_data['produceUnit'] = produceUnit
        shared_data['detectPlace'] = detectPlace
        shared_data['detectBasis'] = detectBasis

        print(shared_data)

        # 获取文本框的内容并发送信号
        texts = [self.comboBox.currentText(), self.comboBox_2.currentText(), self.comboBox_3.currentText(),self.comboBox_4.currentText(),
                 self.comboBox_5.currentText(), self.comboBox_6.currentText(), self.comboBox_9.currentText(), self.comboBox_11.currentText(),
                 self.lineEdit.text(), self.lineEdit_2.text(), self.lineEdit_3.text(), self.lineEdit_4.text()]
        self.textUpdated.emit(texts)

        #添加一个弹窗提示保存成功
        QMessageBox.information(self, "提示", "保存成功！", QMessageBox.Yes)

